#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define MAX_ENTRIES 64
#define BUFFER_SIZE 4096

typedef struct {
    uint8_t *data;
    size_t capacity;
    size_t used;
} Buffer;

typedef struct {
    uint16_t type;
    int16_t length;  /* signed for delta-encoding support */
    uint32_t offset;
} EntryHeader;

static Buffer *create_buffer(size_t size) {
    Buffer *buf = (Buffer *)malloc(sizeof(Buffer));
    if (!buf) return NULL;
    buf->data = (uint8_t *)malloc(size);
    if (!buf->data) { free(buf); return NULL; }
    buf->capacity = size;
    buf->used = 0;
    return buf;
}

static void free_buffer(Buffer *buf) {
    if (buf) {
        free(buf->data);
        free(buf);
    }
}

/* Validate that a write at the given offset with given length fits in buffer */
static int check_bounds(Buffer *buf, size_t offset, size_t length) {
    /* Ensure offset is within buffer */
    if (offset >= buf->capacity) return 0;

    /* Calculate remaining space after offset */
    size_t remaining = buf->capacity - offset;

    /* Ensure length fits in remaining space */
    if (length > remaining) return 0;

    return 1;
}

/* Parse entry headers from raw input */
static int parse_entries(const uint8_t *input, size_t input_len,
                         EntryHeader *entries, int *num_entries) {
    if (input_len < 4) return -1;

    uint16_t count = (input[0] << 8) | input[1];
    uint16_t version = (input[2] << 8) | input[3];

    if (version != 0x0001) return -1;
    if (count > MAX_ENTRIES) return -1;

    size_t pos = 4;
    for (int i = 0; i < count; i++) {
        if (pos + 8 > input_len) return -1;

        entries[i].type = (input[pos] << 8) | input[pos+1];
        entries[i].length = (int16_t)((input[pos+2] << 8) | input[pos+3]);
        entries[i].offset = (uint32_t)((input[pos+4] << 24) | (input[pos+5] << 16) |
                                        (input[pos+6] << 8) | input[pos+7]);
        pos += 8;
    }

    *num_entries = count;
    return (int)pos;
}

/* Copy entry data into output buffer based on headers */
static int materialize_entries(const uint8_t *input, size_t input_len,
                               int data_start, EntryHeader *entries,
                               int num_entries, Buffer *output) {
    for (int i = 0; i < num_entries; i++) {
        EntryHeader *e = &entries[i];

        /* Skip entries with zero or negative length (delta markers) */
        if (e->length <= 0) continue;

        size_t safe_length = (size_t)(uint16_t)e->length;
        size_t safe_offset = (size_t)e->offset;

        /* Validate source bounds */
        if (safe_offset > input_len || safe_length > input_len ||
            (size_t)data_start + safe_offset + safe_length > input_len) return -1;

        /* Validate destination bounds */
        if (!check_bounds(output, safe_offset, safe_length)) return -1;

        /* Copy data */
        memcpy(output->data + safe_offset, 
               input + data_start + safe_offset,
               safe_length);

        if (safe_offset + safe_length > output->used)
            output->used = safe_offset + safe_length;
    }
    return 0;
}

/* Process a complete message: parse headers, allocate output, materialize */
int process_message(const uint8_t *raw, size_t raw_len, uint8_t **out, size_t *out_len) {
    EntryHeader entries[MAX_ENTRIES];
    int num_entries = 0;

    int data_start = parse_entries(raw, raw_len, entries, &num_entries);
    if (data_start < 0) return -1;

    /* Compute required output size from entries */
    size_t max_extent = 0;
    for (int i = 0; i < num_entries; i++) {
        if (entries[i].length <= 0) continue;
        size_t safe_len = (size_t)(uint16_t)entries[i].length;
        size_t extent = (size_t)entries[i].offset + safe_len;
        if (extent > max_extent) max_extent = extent;
    }

    if (max_extent == 0 || max_extent > BUFFER_SIZE) return -1;

    Buffer *output = create_buffer(max_extent);
    if (!output) return -1;

    if (materialize_entries(raw, raw_len, data_start, entries,
                           num_entries, output) != 0) {
        free_buffer(output);
        return -1;
    }

    *out = output->data;
    *out_len = output->used;
    free(output);  /* free struct but not data */
    return 0;
}

/* Second pass: apply delta patches from negative-length entries */
int apply_deltas(const uint8_t *raw, size_t raw_len, uint8_t *buf, size_t buf_len) {
    if (raw_len < 4) return -1;

    uint16_t count = (raw[0] << 8) | raw[1];
    if (count > MAX_ENTRIES) return -1;

    size_t pos = 4;
    for (int i = 0; i < count; i++) {
        if (pos + 8 > raw_len) return -1;

        int16_t length = (int16_t)((raw[pos+2] << 8) | raw[pos+3]);
        uint32_t offset = (uint32_t)((raw[pos+4] << 24) | (raw[pos+5] << 16) |
                                      (raw[pos+6] << 8) | raw[pos+7]);
        pos += 8;

        /* Only process delta entries (negative length) */
        if (length >= 0) continue;

        /* Convert negative length to actual patch size */
        size_t patch_len = (size_t)(uint16_t)(-length);

        /* Bounds check: offset + patch_len must fit in buffer */
        if (offset >= buf_len || patch_len > buf_len - offset) return -1;

        /* Source bounds check */
        size_t src_offset = 4 + ((size_t)count * 8) + (size_t)offset;
        if (src_offset >= raw_len || patch_len > raw_len - src_offset) return -1;

        /* Apply XOR delta patch */
        for (size_t j = 0; j < patch_len; j++) {
            buf[offset + j] ^= raw[src_offset + j];
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;

    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fsize <= 0 || fsize > 65536) { fclose(f); return 1; }

    uint8_t *raw = (uint8_t *)malloc((size_t)fsize);
    if (!raw) { fclose(f); return 1; }
    if (fread(raw, 1, (size_t)fsize, f) != (size_t)fsize) {
        free(raw); fclose(f); return 1;
    }
    fclose(f);

    uint8_t *output = NULL;
    size_t output_len = 0;

    if (process_message(raw, (size_t)fsize, &output, &output_len) == 0) {
        apply_deltas(raw, (size_t)fsize, output, output_len);
        /* Use output... */
        free(output);
    }

    free(raw);
    return 0;
}
